<?php require_once 'includes/functions.php';if(me())go('dashboard.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$bg=$_POST['blood_group']??'';$loc=trim($_POST['location']??'');$role=$_POST['role']??'patient';$pw=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$loc||strlen($pw)<8||!in_array($role,['patient','donor'])||!in_array($bg,['A+','A-','B+','B-','AB+','AB-','O+','O-']))$err='Check the required fields and use a password of at least 8 characters.';else try{$p=db();$p->beginTransaction();$s=$p->prepare('INSERT INTO users(name,email,phone,password_hash,blood_group,location,role) VALUES(?,?,?,?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT),$bg,$loc,$role]);$id=(int)$p->lastInsertId();if($role==='donor')$p->prepare("INSERT INTO donor_profiles(user_id) VALUES(?)")->execute([$id]);$p->commit();flash('Registration complete. Please log in.');go('login.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err='Could not register. This email may already exist.';}}$title='Register';require 'includes/header.php';?><section class="form"><h1>Create account</h1><?php if($err):?><p class="alert error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Blood group<select name="blood_group"><?php foreach(['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $b):?><option><?=e($b)?></option><?php endforeach;?></select></label><label>Location<input name="location" required placeholder="Kathmandu"></label><label>Account type<select name="role"><option value="patient">Patient / requester</option><option value="donor">Donor</option></select></label><label>Password (8+ characters)<input type="password" name="password" minlength="8" required></label><button class="btn">Register</button></form><p>Already registered? <a href="login.php">Login</a></p></section><?php require 'includes/footer.php';?>